// Client Componentでユーザー操作時にデータフェッチ
'use client';

import { useQuery } from '@tanstack/react-query';
import { searchProducts } from '@/apis/products.client';

export function SearchResults({ query }: { query: string }) {
  const { data, isLoading, error } = useQuery({
    queryKey: ['products', 'search', query],
    queryFn: () => searchProducts(query), // Route Handlerを経由
    enabled: query.length > 0,
    staleTime: 5 * 60 * 1000, // 5分
  });

  if (isLoading) return <Loading />;
  if (error) return <Error message={error.message} />;

  return (
    <ul>
      {data?.products.map(p => <ProductCard key={p.id} product={p} />)}
    </ul>
  );
}

// Server Componentで検索条件を取得
type Props = {
  searchParams: { q?: string; page?: string };
};

export default async function SearchPage({ searchParams }: Props) {
  const query = searchParams.q || '';
  const page = Number(searchParams.page) || 1;

  return (
    <div>
      <SearchForm initialQuery={query} />
      <SearchResults query={query} page={page} />
    </div>
  );
}

// Client Componentで検索条件を更新
'use client';

import { useRouter } from 'next/navigation';

export function SearchForm({ initialQuery }: { initialQuery: string }) {
  const router = useRouter();
  const [query, setQuery] = useState(initialQuery);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    router.replace(`/search?q=${encodeURIComponent(query)}`);
  };

  return (
    <form onSubmit={handleSubmit}>
      <input value={query} onChange={(e) => setQuery(e.target.value)} />
      <button type="submit">Search</button>
    </form>
  );
}

'use client';

import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';

const schema = z.object({
  name: z.string().min(1, 'Name is required'),
  email: z.string().email('Invalid email'),
});

type FormData = z.infer<typeof schema>;

export function UserForm() {
  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm<FormData>({
    resolver: zodResolver(schema),
  });

  const onSubmit = (data: FormData) => {
    console.log(data);
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)}>
      <input {...register('name')} />
      {errors.name && <p>{errors.name.message}</p>}

      <input {...register('email')} />
      {errors.email && <p>{errors.email.message}</p>}

      <button type="submit">Submit</button>
    </form>
  );
}

'use client';

import { useEffect, useState } from 'react';

export function DraftEditor() {
  const [content, setContent] = useState('');

  // localStorageから復元
  useEffect(() => {
    const draft = localStorage.getItem('draft');
    if (draft) setContent(draft);
  }, []);

  // localStorageに保存
  const handleChange = (value: string) => {
    setContent(value);
    localStorage.setItem('draft', value);
  };

  return (
    <textarea
      value={content}
      onChange={(e) => handleChange(e.target.value)}
    />
  );
}

// Server Actionでセッションを作成（httpOnly Cookie）
import { cookies } from 'next/headers';

export async function login(email: string, password: string) {
  // ユーザー認証
  const user = await authenticateUser(email, password);
  if (!user) {
    return { isSuccess: false, errorMessage: 'Invalid credentials' };
  }

  // セッショントークンを生成
  const sessionToken = await createSessionToken(user.id);

  // httpOnly Cookieに保存（JavaScriptからアクセス不可）
  cookies().set('session', sessionToken, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    maxAge: 60 * 60 * 24 * 7, // 7日間
  });

  return { isSuccess: true, data: user };
}

// Server Componentでセッションを取得
export async function getSession() {
  const sessionToken = cookies().get('session')?.value;
  if (!sessionToken) return null;

  return await validateSessionToken(sessionToken);
}
